V2 = {'backend/app/api/margin_log_routes.py': '# backend/app/api/margin_log_routes.py\n#\n# ── MARGIN_LOG_20261016 ── how much money does each strategy REALLY need?\n# ── MARGIN_LOG_ENTRY_20261016 ── plus: the margin AT ENTRY.\n#\n# The job runs every minute of the NFO session (holiday-aware). Each minute it\n# reads every strategy\'s OPEN legs per book (PAPER / LIVE) from\n# fleet_today_routes._legs_for — the dashboard\'s own reader; a DB read, no\n# Kite call — and compares them with what was last recorded:\n#\n#   ENTRY   the strategy-book was flat and now holds legs   → margin call\n#   CHANGE  its legs changed (adjustment, roll, one leg out) → margin call\n#   CLOSED  it went flat                                     → zero row, NO call\n#   TIMER   every 5th minute 09:20–15:25: every open book    → margin call\n#   MANUAL  "Sample now" (any time)                          → margin call\n#\n# Change samples start at 09:17 IST — one minute after the 09:16 entries, so a\n# recording tool never adds Kite calls inside the open\'s order burst (the\n# 8–11 Sep rate-limit scars) — and run until 15:29 to see the 15:26 exits. At\n# most MAX_CHANGE_CALLS change samples per minute, CALL_GAP_S apart; the rest\n# wait for the next minute (their recorded legs are only updated once a row is\n# written, so nothing is lost, just delayed).\n#\n# Margin = kite.basket_order_margins(consider_positions=False) — what that\n# basket alone blocks — BUY legs first (live sequencing → spread benefit),\n# product NRML. Places no orders; touches no engine.\n#\n# Per-lot unit: `base_lots` = lots of the largest SELL leg (the leg that\n# drives SPAN); a buy-only strategy uses its largest leg. legs_json keeps\n# every leg so other normalisations can be recomputed from the export.\n#\n# Fleet "at once" per book: within a day, each strategy\'s latest row is\n# carried forward (a CLOSED row zeroes it), and the books are summed at every\n# sample time — so a change sample of one strategy no longer under-counts the\n# others, and the 09:17–09:19 entry minutes are part of the peak.\n#\n# Never raises out of the job; a failed margin call is stored with `error`.\n\nfrom __future__ import annotations\n\nimport json\nimport sqlite3\nimport statistics\nimport threading\nimport time\nfrom typing import Dict, List, Optional, Tuple\n\nfrom fastapi import APIRouter\n\nrouter = APIRouter(tags=["margin-log"])\n\nFENCE = "MARGIN_LOG_20261016"\nFENCE_ENTRY = "MARGIN_LOG_ENTRY_20261016"\nIST_OFF = 5 * 3600 + 30 * 60\nCHANGE_FROM_MIN = 9 * 60 + 17      # first change sample: a minute after the 09:16 entries\nCHANGE_TO_MIN = 15 * 60 + 29       # see the 15:26 exits\nTIMER_FROM_MIN = 9 * 60 + 20       # regular samples, every 5th minute\nTIMER_TO_MIN = 15 * 60 + 25\nTIMER_EVERY_MIN = 5\nMAX_CHANGE_CALLS = 6                # change-triggered margin calls per minute\nKEEP_DAYS = 180\nDEFAULT_LOT = 65\nCALL_GAP_S = 0.35                   # between margin calls (Kite rate limits)\nSEED_LOOKBACK_S = 5 * 86400         # recorded-legs memory is seeded from the DB on boot\n_lock = threading.Lock()\n_last: Dict[Tuple[str, str], tuple] = {}     # (sid, book) → recorded leg signature (() = flat)\n_seeded = [False]\n\n\n# ───────────────────────────── plumbing ──────────────────────────────────\n\ndef _db_path() -> str:\n    from app.api import fleet_today_routes as F\n    return F._db_path()\n\n\ndef _ensure_table(conn) -> None:\n    conn.execute(\n        "CREATE TABLE IF NOT EXISTS margin_samples ("\n        " ts INTEGER NOT NULL, day TEXT NOT NULL, hhmm TEXT NOT NULL,"\n        " strategy_id TEXT NOT NULL, book TEXT NOT NULL, mode TEXT,"\n        " n_legs INTEGER, base_lots REAL, total REAL, span REAL, exposure REAL,"\n        " premium REAL, per_lot REAL, legs_json TEXT, error TEXT)")\n    cols = {r[1] for r in conn.execute("PRAGMA table_info(margin_samples)")}\n    if "trigger" not in cols:                                     # ── MARGIN_LOG_ENTRY_20261016 ──\n        conn.execute("ALTER TABLE margin_samples ADD COLUMN trigger TEXT")\n    conn.execute("CREATE INDEX IF NOT EXISTS idx_margin_samples_sid_day"\n                 " ON margin_samples(strategy_id, day)")\n    conn.execute("CREATE INDEX IF NOT EXISTS idx_margin_samples_ts ON margin_samples(ts)")\n\n\ndef _ist_min(ts: int) -> int:\n    return ((int(ts) + IST_OFF) % 86400) // 60\n\n\ndef _day(ts: int) -> str:\n    return time.strftime("%Y-%m-%d", time.gmtime(int(ts) + IST_OFF))\n\n\ndef _hhmm(ts: int) -> str:\n    m = _ist_min(ts)\n    return f"{m // 60:02d}:{m % 60:02d}"\n\n\ndef _in_change_window(ts: int) -> bool:\n    return CHANGE_FROM_MIN <= _ist_min(ts) <= CHANGE_TO_MIN\n\n\ndef _is_timer_minute(ts: int) -> bool:\n    m = _ist_min(ts)\n    return TIMER_FROM_MIN <= m <= TIMER_TO_MIN and m % TIMER_EVERY_MIN == 0\n\n\ndef _in_window(ts: int) -> bool:          # kept for callers of the first version\n    return _is_timer_minute(ts) or _in_change_window(ts)\n\n\ndef _market_open() -> bool:\n    from app.api import fleet_today_routes as F\n    return F._market_open()\n\n\ndef _kite():\n    from kiteconnect import KiteConnect\n    from app.brokers.zerodha_manager import load_access_token, load_credentials\n    api_key = (load_credentials() or {}).get("api_key")\n    token = load_access_token()\n    if not api_key or not token:\n        return None\n    k = KiteConnect(api_key=api_key)\n    k.set_access_token(token)\n    return k\n\n\n_lot_cache: Dict[str, int] = {}\n\n\ndef _lot_size(symbol: str) -> int:\n    if symbol in _lot_cache:\n        return _lot_cache[symbol]\n    lot = DEFAULT_LOT\n    try:\n        from app.fetcher.zerodha_instruments import load_instruments_df\n        df = load_instruments_df()\n        hit = df[df["tradingsymbol"] == symbol]\n        if len(hit):\n            lot = int(hit["lot_size"].iloc[0]) or DEFAULT_LOT\n    except Exception:\n        pass\n    _lot_cache[symbol] = lot\n    return lot\n\n\ndef _exchange(symbol: str) -> str:\n    s = symbol.upper()\n    return "BFO" if s.startswith(("SENSEX", "BANKEX")) else "NFO"\n\n\n# ───────────────────────────── one basket ────────────────────────────────\n\ndef basket_for(legs: List[dict]) -> List[dict]:\n    """Open normalised legs → Kite basket, BUY legs first. Pure."""\n    out = []\n    for l in legs:\n        sym, qty = str(l.get("symbol") or ""), int(l.get("qty") or 0)\n        if not sym or qty <= 0:\n            continue\n        out.append({"exchange": _exchange(sym), "tradingsymbol": sym,\n                    "transaction_type": "SELL" if l.get("short") else "BUY",\n                    "variety": "regular", "product": "NRML", "order_type": "MARKET",\n                    "quantity": qty, "price": 0, "trigger_price": 0})\n    out.sort(key=lambda o: 0 if o["transaction_type"] == "BUY" else 1)\n    return out\n\n\ndef signature(basket: List[dict]) -> tuple:\n    """Order-free identity of a basket: what counts as \'the legs changed\'. Pure."""\n    return tuple(sorted((o["tradingsymbol"], o["transaction_type"][0], int(o["quantity"])) for o in basket))\n\n\ndef _sig_from_json(legs_json: Optional[str]) -> tuple:\n    try:\n        return tuple(sorted((d["s"], d["t"], int(d["q"])) for d in json.loads(legs_json or "[]")))\n    except Exception:\n        return ()\n\n\ndef base_lots(basket: List[dict]) -> float:\n    """Lots of the largest SELL leg; buy-only → largest leg. Pure."""\n    sells = [o for o in basket if o["transaction_type"] == "SELL"]\n    pool = sells or basket\n    if not pool:\n        return 0.0\n    return max(o["quantity"] / float(_lot_size(o["tradingsymbol"])) for o in pool)\n\n\ndef _f(d: dict, *keys) -> Optional[float]:\n    for k in keys:\n        v = (d or {}).get(k)\n        if v is not None:\n            try:\n                return float(v)\n            except (TypeError, ValueError):\n                pass\n    return None\n\n\ndef measure(kite, legs: List[dict]) -> dict:\n    """Margin for one strategy-book\'s open legs. Never raises."""\n    basket = basket_for(legs)\n    rec = {"n_legs": len(basket), "base_lots": round(base_lots(basket), 3),\n           "legs_json": json.dumps([{"s": o["tradingsymbol"], "t": o["transaction_type"][0],\n                                     "q": o["quantity"]} for o in basket], separators=(",", ":")),\n           "total": None, "span": None, "exposure": None, "premium": None, "per_lot": None,\n           "error": None, "sig": signature(basket)}\n    if not basket:\n        rec["error"] = "no priceable legs"\n        return rec\n    try:\n        resp = kite.basket_order_margins(basket, consider_positions=False)\n        fin = (resp or {}).get("final") or {}\n        tot = _f(fin, "total")\n        if tot is None:\n            raise ValueError("no final.total in margin response")\n        rec.update(total=round(tot, 2), span=_f(fin, "span"), exposure=_f(fin, "exposure"),\n                   premium=_f(fin, "option_premium"))\n        if rec["base_lots"]:\n            rec["per_lot"] = round(tot / rec["base_lots"], 2)\n    except Exception as e:\n        rec["error"] = f"{type(e).__name__}: {e}"[:300]\n    return rec\n\n\n# ───────────────────────────── the sampler ───────────────────────────────\n\ndef _seed(now: int) -> None:\n    """Recorded-legs memory survives a restart: each (strategy, book)\'s latest\n    row in the last few days (a CLOSED / 0-leg row = flat)."""\n    if _seeded[0]:\n        return\n    _seeded[0] = True\n    try:\n        with sqlite3.connect(_db_path(), timeout=30) as conn:\n            _ensure_table(conn)\n            latest: Dict[Tuple[str, str], tuple] = {}\n            for sid, book, legs_json, n in conn.execute(\n                    "SELECT strategy_id, book, legs_json, n_legs FROM margin_samples"\n                    " WHERE ts >= ? ORDER BY ts", (now - SEED_LOOKBACK_S,)):\n                latest[(sid, book)] = _sig_from_json(legs_json) if n else ()\n            for key, sig in latest.items():\n                _last.setdefault(key, sig)\n    except Exception:\n        pass\n\n\ndef _row(now: int, sid: str, book: str, mode: str, rec: dict, trigger: str) -> tuple:\n    return (now, _day(now), _hhmm(now), sid, book, mode, rec["n_legs"], rec["base_lots"],\n            rec["total"], rec["span"], rec["exposure"], rec["premium"], rec["per_lot"],\n            rec["legs_json"], rec["error"], trigger)\n\n\ndef sample_now(now: Optional[int] = None, force: bool = False, kite=None) -> dict:\n    """One minute\'s pass. force=True = MANUAL full pass at any time.\n    Otherwise: NFO session only; ENTRY/CHANGE/CLOSED from 09:17 to 15:29,\n    TIMER every 5th minute 09:20–15:25. Never raises."""\n    now = int(now or time.time())\n    try:\n        timer = force or _is_timer_minute(now)\n        if not force and (not _market_open() or not _in_change_window(now)):\n            return {"sampled": False, "reason": "outside sampling window"}\n        if not _lock.acquire(blocking=False):\n            return {"sampled": False, "reason": "a sample is already running"}\n        try:\n            from app.api import fleet_today_routes as F\n            _seed(now)\n            warns: list = []\n            groups: Dict[Tuple[str, str], tuple] = {}     # (sid, book) → (mode, legs, basket sig)\n            unreadable = set()\n            for sid in F.FLEET_IDS:\n                if not F._allowed(sid):\n                    continue\n                try:\n                    legs = F._legs_for(sid, warns)\n                except Exception as e:\n                    warns.append(f"{sid}: {e!r}")\n                    unreadable.add(sid)\n                    continue\n                mode = F._mode(sid)\n                for book in F.BOOKS:\n                    mine = [l for l in legs if l.get("open") and l.get("book") == book]\n                    if mine:\n                        groups[(sid, book)] = (mode, mine, signature(basket_for(mine)))\n            rows: List[tuple] = []\n            # CLOSED: was holding, now flat (never for a strategy we could not read)\n            for key, sig in list(_last.items()):\n                if sig and key not in groups and key[0] not in unreadable and (force or _in_change_window(now)):\n                    rows.append((now, _day(now), _hhmm(now), key[0], key[1], None, 0, 0, 0.0, None, None,\n                                 None, None, "[]", None, "CLOSED"))\n                    _last[key] = ()\n            # what needs a margin call this minute\n            todo: List[Tuple[Tuple[str, str], str]] = []\n            changed = []\n            for key, (mode, mine, sig) in groups.items():\n                prev = _last.get(key)\n                if prev != sig:\n                    changed.append((key, "ENTRY" if not prev else "CHANGE"))\n            if timer:\n                ch = dict(changed)\n                todo = [(k, ch.get(k, "MANUAL" if force else "TIMER")) for k in groups]\n            else:\n                changed.sort(key=lambda kv: 0 if kv[1] == "ENTRY" else 1)   # entries first\n                todo = changed[:MAX_CHANGE_CALLS]\n            deferred = max(0, len(changed) - len(todo)) if not timer else 0\n            if todo:\n                if kite is None:\n                    kite = _kite() or _NoKite()\n                for i, (key, trig) in enumerate(todo):\n                    mode, mine, sig = groups[key]\n                    if i:\n                        time.sleep(CALL_GAP_S)\n                    rec = measure(kite, mine)\n                    rows.append(_row(now, key[0], key[1], mode, rec, trig))\n                    _last[key] = sig          # recorded (an error row too — no hammering)\n            if rows:\n                with sqlite3.connect(_db_path(), timeout=30) as conn:\n                    _ensure_table(conn)\n                    conn.executemany("INSERT INTO margin_samples (ts, day, hhmm, strategy_id, book, mode,"\n                                     " n_legs, base_lots, total, span, exposure, premium, per_lot, legs_json,"\n                                     " error, trigger) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", rows)\n                    conn.execute("DELETE FROM margin_samples WHERE ts < ?", (now - KEEP_DAYS * 86400,))\n            calls = [r for r in rows if r[-1] != "CLOSED"]\n            return {"sampled": True, "rows": len(rows), "calls": len(calls),\n                    "errors": sum(1 for r in calls if r[14]), "deferred": deferred,\n                    "triggers": sorted({r[-1] for r in rows}),\n                    "reason": None if rows else ("no open positions" if not groups else "no change"),\n                    "warnings": warns}\n        finally:\n            _lock.release()\n    except Exception as e:\n        return {"sampled": False, "reason": repr(e)}\n\n\nclass _NoKite:\n    def basket_order_margins(self, *a, **k):\n        raise RuntimeError("Zerodha session not available — log in")\n\n\ndef margin_log_sample_job() -> None:\n    """APScheduler entry point (cron every minute, 09–15 Mon–Fri IST; the\n    session / 09:17–15:29 / timer logic lives in sample_now). Never raises."""\n    try:\n        r = sample_now()\n        if not r.get("sampled") and r.get("reason") not in (None, "outside sampling window",\n                                                             "a sample is already running"):\n            from app.event_bus.audit_logger import write_audit_log\n            write_audit_log(f"[MARGIN_LOG][WARN] {r.get(\'reason\')}")\n    except Exception:\n        pass\n\n\n# ───────────────────────────── reading ───────────────────────────────────\n\ndef _rows(days: int, strategy_id: Optional[str] = None, book: Optional[str] = None,\n          now: Optional[int] = None) -> List[dict]:\n    now = int(now or time.time())\n    q = "SELECT * FROM margin_samples WHERE ts >= ?"\n    args: list = [now - int(days) * 86400]\n    if strategy_id:\n        q += " AND strategy_id = ?"; args.append(strategy_id)\n    if book in ("LIVE", "PAPER"):\n        q += " AND book = ?"; args.append(book)\n    q += " ORDER BY ts, strategy_id, book"\n    with sqlite3.connect(_db_path(), timeout=30) as conn:\n        _ensure_table(conn)\n        conn.row_factory = sqlite3.Row\n        return [dict(r) for r in conn.execute(q, args)]\n\n\ndef _pct(xs: List[float], p: float) -> Optional[float]:\n    if not xs:\n        return None\n    xs = sorted(xs)\n    k = (len(xs) - 1) * p\n    lo, hi = int(k), min(int(k) + 1, len(xs) - 1)\n    return round(xs[lo] + (xs[hi] - xs[lo]) * (k - lo), 2)\n\n\ndef fleet_concurrent(rows: List[dict], book: str) -> Dict[int, float]:\n    """Σ per sample time of each strategy\'s LATEST margin that day (carried\n    forward; a CLOSED row zeroes it; an error row keeps the last good value).\n    Pure."""\n    out: Dict[int, float] = {}\n    cur: Dict[str, float] = {}\n    day = None\n    for r in sorted((r for r in rows if r["book"] == book), key=lambda r: (r["ts"], r["strategy_id"])):\n        if r["day"] != day:\n            day, cur = r["day"], {}\n        if r.get("trigger") == "CLOSED" or not r.get("n_legs"):\n            cur[r["strategy_id"]] = 0.0\n        elif r.get("total") is not None:\n            cur[r["strategy_id"]] = float(r["total"])\n        out[r["ts"]] = round(sum(cur.values()), 2)\n    return out\n\n\ndef summarise(rows: List[dict]) -> dict:\n    """Per (strategy, book) stats + fleet-concurrent per book. Pure."""\n    by: Dict[tuple, List[dict]] = {}\n    for r in rows:\n        if r.get("trigger") == "CLOSED" or not r.get("n_legs"):\n            continue                                   # a flat marker, not a margin sample\n        by.setdefault((r["strategy_id"], r["book"]), []).append(r)\n    out = []\n    for (sid, book), rs in sorted(by.items()):\n        ok = [r for r in rs if r.get("total") is not None]\n        tot = [float(r["total"]) for r in ok]\n        pl = [float(r["per_lot"]) for r in ok if r.get("per_lot") is not None]\n        lots = [r["base_lots"] for r in ok if r.get("base_lots")]\n        ent = [float(r["total"]) for r in ok if r.get("trigger") == "ENTRY"]\n        ent_pl = [float(r["per_lot"]) for r in ok if r.get("trigger") == "ENTRY" and r.get("per_lot") is not None]\n        peak = max(ok, key=lambda r: r["total"]) if ok else None\n        out.append({\n            "strategy_id": sid, "book": book, "samples": len(ok), "errors": len(rs) - len(ok),\n            "days": len({r["day"] for r in ok}),\n            "lots_typical": (statistics.mode(lots) if lots else None),\n            "lots_max": (max(lots) if lots else None),\n            "median": _pct(tot, 0.5), "p90": _pct(tot, 0.9), "peak": (round(max(tot), 2) if tot else None),\n            "peak_at": (f"{peak[\'day\']} {peak[\'hhmm\']}" if peak else None),\n            "peak_lots": (peak["base_lots"] if peak else None),\n            "per_lot_median": _pct(pl, 0.5), "per_lot_p90": _pct(pl, 0.9),\n            "per_lot_peak": (round(max(pl), 2) if pl else None),\n            "entries": len(ent), "entry_median": _pct(ent, 0.5),\n            "entry_peak": (round(max(ent), 2) if ent else None),\n            "entry_per_lot_median": _pct(ent_pl, 0.5),\n            "last_ts": max(r["ts"] for r in rs),\n            "last_error": next((r["error"] for r in sorted(rs, key=lambda r: -r["ts"]) if r.get("error")), None),\n        })\n    fleet = {}\n    for book in ("LIVE", "PAPER"):\n        per_ts = {t: v for t, v in fleet_concurrent(rows, book).items() if v > 0}\n        if per_ts:\n            t_peak = max(per_ts, key=per_ts.get)\n            vals = list(per_ts.values())\n            fleet[book] = {"samples": len(per_ts), "median": _pct(vals, 0.5), "p90": _pct(vals, 0.9),\n                           "peak": round(per_ts[t_peak], 2), "peak_at": f"{_day(t_peak)} {_hhmm(t_peak)}"}\n    return {"strategies": out, "fleet": fleet}\n\n\n@router.get("/api/margin-log/summary")\ndef get_summary(days: int = 14, book: str = "ALL"):\n    try:\n        rows = _rows(max(1, min(int(days), KEEP_DAYS)), book=book.upper())\n        s = summarise(rows)\n        first = min((r["ts"] for r in rows), default=None)\n        return {"ok": True, "days": days, "first_ts": first, "rows": len(rows), **s,\n                "window": "on every entry / leg change from 09:17, and every 5 min 09:20–15:25 IST",\n                "keep_days": KEEP_DAYS}\n    except Exception as e:\n        return {"ok": False, "error": repr(e), "strategies": [], "fleet": {}}\n\n\n@router.get("/api/margin-log/samples")\ndef get_samples(days: int = 14, strategy_id: Optional[str] = None, book: str = "ALL", limit: int = 20000):\n    try:\n        rows = _rows(max(1, min(int(days), KEEP_DAYS)), strategy_id=strategy_id, book=book.upper())\n        return {"ok": True, "rows": rows[-max(1, min(int(limit), 50000)):]}\n    except Exception as e:\n        return {"ok": False, "error": repr(e), "rows": []}\n\n\n@router.post("/api/margin-log/sample-now")\ndef post_sample_now():\n    """Manual full pass (works outside hours — margins use current prices)."""\n    return sample_now(force=True)\n', 'backend/app/api/test_margin_log.py': '# backend/app/api/test_margin_log.py — fences MARGIN_LOG_20261016 + MARGIN_LOG_ENTRY_20261016\n#\n# Margin log sampler + summary, on a temp app.db with a fake Kite and fake\n# fleet legs. No network, no broker session, no TestClient (Build-Mac rule).\n# Every time below is a REAL epoch second for an IST wall-clock time.\n#\n#   1. basket: BUY legs first, NRML; signature ignores leg order\n#   2. base_lots = largest SELL leg (IC 10 shorts + 8 ADJ → 10); buy-only → largest\n#   3. gate: 09:16 nothing; 09:17 ENTRY samples; 09:18 unchanged → no Kite call;\n#      a new leg → CHANGE; 09:20 TIMER samples every open book; 15:26 CLOSED\n#      rows; 15:30 nothing; market closed nothing; force = MANUAL any time\n#   4. cap: 8 entries in one minute → 6 calls (entries first), 2 deferred to\n#      the next minute, none lost\n#   5. CLOSED = zero row with NO margin call; an unreadable strategy is never\n#      marked closed; restart seeds the recorded legs from the DB (no re-ENTRY)\n#   6. failures: a failing call is stored with its error, the pass continues;\n#      no Kite session → error rows, no crash\n#   7. summary: per strategy median / p90 / peak + at-entry median / peak;\n#      CLOSED rows excluded; fleet "at once" carries each strategy\'s latest\n#      value forward within a day (an entry minute counts) and a CLOSED zeroes\n#   8. migration: a first-version table (no trigger column) is upgraded and\n#      its rows still count; retention purge; overlap refused; job never raises\n#\n# Run: cd backend && python3 app/api/test_margin_log.py\n\nfrom __future__ import annotations\n\nimport calendar\nimport os\nimport sqlite3\nimport sys\nimport tempfile\nfrom pathlib import Path\n\nHERE = Path(__file__).resolve()\nBACKEND = str(HERE.parents[2])\nif BACKEND not in sys.path:\n    sys.path.insert(0, BACKEND)\n\nFAILS: list = []\nOK = [0]\n\n\ndef check(name, ok, note=""):\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}{(\'  — \' + str(note)) if (note and not ok) else \'\'}")\n    if ok:\n        OK[0] += 1\n    else:\n        FAILS.append(name)\n\n\ndef ist(h, mi, d=19, mo=10, y=2026):\n    return calendar.timegm((y, mo, d, h, mi, 0)) - (5 * 3600 + 30 * 60)\n\n\ndef leg(sym, qty, short, open_=True, book="PAPER"):\n    return {"symbol": sym, "qty": qty, "short": short, "open": open_, "book": book}\n\n\nclass FakeKite:\n    def __init__(self, fail=()):\n        self.calls, self.fail = [], set(fail)\n\n    def basket_order_margins(self, basket, consider_positions=False):\n        self.calls.append((basket, consider_positions))\n        if any(o["tradingsymbol"] in self.fail for o in basket):\n            raise RuntimeError("InputException: bad symbol")\n        tot = sum((100000.0 if o["transaction_type"] == "SELL" else 5000.0) * o["quantity"] / 65 for o in basket)\n        return {"final": {"total": tot, "span": tot * 0.7, "exposure": tot * 0.3, "option_premium": 1}}\n\n\ndef setup():\n    import app.api.margin_log_routes as M\n    import app.api.fleet_today_routes as F\n    td = tempfile.mkdtemp()\n    db = os.path.join(td, "app.db")\n    M._db_path = lambda: db\n    M.CALL_GAP_S = 0\n    M._lot_size = lambda s: 65\n    M._last.clear(); M._seeded[0] = False\n    FLEET: dict = {}\n    F.FLEET_IDS = ["IC_V2", "TSG_V1", "ORB_V1", "BRK_V1", "HA_V1", "EMC_V1", "VET_V1", "TMA_V2", "BB_V1"]\n    F._allowed = lambda sid: True\n    F._mode = lambda sid: "PAPER"\n    F._legs_for = lambda sid, w: [dict(l) for l in FLEET.get(sid, [])]\n    F._market_open = lambda: True\n    return M, F, FLEET, db\n\n\ndef rows_at(M, ts):\n    return [r for r in M._rows(30, now=ts + 60) if r["ts"] == ts]\n\n\nIC = [leg("ICX24000CE", 650, True), leg("ICX23000PE", 650, True), leg("ICX24500CE", 650, False), leg("ICX22500PE", 650, False)]\nTSG = [leg("TSGX24300CE", 130, True), leg("TSGX22700PE", 130, True)]\n\n\ndef main():\n    print("── 1–2. basket / signature / lots ──")\n    M, F, FLEET, db = setup()\n    b = M.basket_for(IC + [leg("ADJX24100CE", 520, False)])\n    check("BUY legs first, NRML", [o["transaction_type"] for o in b] == ["BUY"] * 3 + ["SELL"] * 2 and all(o["product"] == "NRML" for o in b))\n    check("signature ignores leg order", M.signature(M.basket_for(IC)) == M.signature(M.basket_for(list(reversed(IC)))))\n    check("IC 10 shorts + 8 ADJ → base 10 lots", M.base_lots(b) == 10)\n    check("buy-only → largest leg", M.base_lots(M.basket_for([leg("A", 650, False), leg("B", 130, False)])) == 10)\n\n    print("── 3. gate + triggers ──")\n    k = FakeKite()\n    FLEET["IC_V2"] = IC; FLEET["TSG_V1"] = TSG\n    r = M.sample_now(now=ist(9, 16), kite=k)\n    check("09:16 → nothing, no Kite call", r["sampled"] is False and not k.calls, r)\n    r = M.sample_now(now=ist(9, 17), kite=k)\n    rs = rows_at(M, ist(9, 17))\n    check("09:17 → ENTRY row for each new position", r["sampled"] and sorted((x["strategy_id"], x["trigger"]) for x in rs)\n          == [("IC_V2", "ENTRY"), ("TSG_V1", "ENTRY")], rs)\n    check("ENTRY margin recorded (IC 2 shorts + 2 wings)", abs(next(x for x in rs if x["strategy_id"] == "IC_V2")["total"] - 2.1e6) < 0.01)\n    n = len(k.calls)\n    r = M.sample_now(now=ist(9, 18), kite=k)\n    check("09:18 unchanged → no rows, no Kite call", r["rows"] == 0 and len(k.calls) == n and r["reason"] == "no change", r)\n    FLEET["IC_V2"] = IC + [leg("ADJX24100CE", 520, False)]\n    M.sample_now(now=ist(9, 19), kite=k)\n    rs = rows_at(M, ist(9, 19))\n    check("new leg (adjustment) → one CHANGE row, IC only", [(x["strategy_id"], x["trigger"]) for x in rs] == [("IC_V2", "CHANGE")], rs)\n    M.sample_now(now=ist(9, 20), kite=k)\n    rs = rows_at(M, ist(9, 20))\n    check("09:20 → TIMER row for every open book", sorted((x["strategy_id"], x["trigger"]) for x in rs) == [("IC_V2", "TIMER"), ("TSG_V1", "TIMER")], rs)\n    n = len(k.calls)\n    M.sample_now(now=ist(9, 21), kite=k)\n    check("09:21 (not a timer minute, no change) → no call", len(k.calls) == n)\n    check("consider_positions=False on every call", all(c[1] is False for c in k.calls))\n    FLEET["TSG_V1"] = []\n    n = len(k.calls)\n    M.sample_now(now=ist(15, 26), kite=k)\n    rs = rows_at(M, ist(15, 26))\n    check("15:26 exit → CLOSED row, zero, no margin call",\n          [(x["strategy_id"], x["trigger"], x["n_legs"], x["total"]) for x in rs] == [("TSG_V1", "CLOSED", 0, 0.0)] and len(k.calls) == n, rs)\n    FLEET["TSG_V1"] = TSG\n    check("15:30 → nothing", M.sample_now(now=ist(15, 30), kite=k)["sampled"] is False)\n    F._market_open = lambda: False\n    check("market closed → nothing", M.sample_now(now=ist(10, 0), kite=k)["sampled"] is False)\n    r = M.sample_now(now=ist(20, 0), force=True, kite=k)\n    rs = rows_at(M, ist(20, 0))\n    check("force → full pass any time; TSG re-entry labelled ENTRY, IC MANUAL",\n          sorted((x["strategy_id"], x["trigger"]) for x in rs) == [("IC_V2", "MANUAL"), ("TSG_V1", "ENTRY")], rs)\n    F._market_open = lambda: True\n\n    print("── 4. per-minute cap ──")\n    M, F, FLEET, db = setup()\n    k = FakeKite()\n    for i, sid in enumerate(F.FLEET_IDS[:8]):\n        FLEET[sid] = [leg(f"{sid}X{i}CE", 650, i % 2 == 0)]\n    r = M.sample_now(now=ist(9, 17), kite=k)\n    check(f"8 entries at 09:17 → {M.MAX_CHANGE_CALLS} calls, 2 deferred", r["calls"] == M.MAX_CHANGE_CALLS and r["deferred"] == 2, r)\n    r = M.sample_now(now=ist(9, 18), kite=k)\n    check("the 2 deferred are sampled at 09:18 as ENTRY", r["calls"] == 2 and r["triggers"] == ["ENTRY"], r)\n    got = {x["strategy_id"] for x in M._rows(30, now=ist(9, 30)) if x["trigger"] == "ENTRY"}\n    check("all 8 entries recorded, none lost", len(got) == 8, got)\n\n    print("── 5. CLOSED rules + restart seed ──")\n    M, F, FLEET, db = setup()\n    k = FakeKite()\n    FLEET["IC_V2"] = IC; FLEET["ORB_V1"] = [leg("ORBX1CE", 650, False)]\n    M.sample_now(now=ist(9, 17), kite=k)\n    F._legs_for = lambda sid, w: (_ for _ in ()).throw(RuntimeError("db busy")) if sid == "ORB_V1" else [dict(l) for l in FLEET.get(sid, [])]\n    M.sample_now(now=ist(9, 18), kite=k)\n    check("unreadable strategy is NOT marked closed", not rows_at(M, ist(9, 18)))\n    F._legs_for = lambda sid, w: [dict(l) for l in FLEET.get(sid, [])]\n    M._last.clear(); M._seeded[0] = False                      # app restart\n    n = len(k.calls)\n    r = M.sample_now(now=ist(9, 19), kite=k)\n    check("restart: recorded legs seeded from the DB → no re-ENTRY, no call", r["rows"] == 0 and len(k.calls) == n, r)\n\n    print("── 6. failures ──")\n    M, F, FLEET, db = setup()\n    FLEET["IC_V2"] = IC; FLEET["ORB_V1"] = [leg("BADX1CE", 650, False)]\n    r = M.sample_now(now=ist(9, 17), kite=FakeKite(fail={"BADX1CE"}))\n    rs = rows_at(M, ist(9, 17))\n    orb = next(x for x in rs if x["strategy_id"] == "ORB_V1")\n    check("failed call stored with error; IC still recorded", "InputException" in (orb["error"] or "") and r["errors"] == 1\n          and next(x for x in rs if x["strategy_id"] == "IC_V2")["total"] is not None, rs)\n    M2, F2, FLEET2, _ = setup()\n    M2._kite = lambda: None\n    FLEET2["IC_V2"] = IC\n    r = M2.sample_now(now=ist(9, 17))\n    check("no Kite session → error row, no crash", r["sampled"] and r["errors"] == 1, r)\n\n    print("── 7. summary + fleet at once ──")\n    M, F, FLEET, db = setup()\n    k = FakeKite()\n    FLEET["IC_V2"] = IC\n    M.sample_now(now=ist(9, 17), kite=k)                       # IC ENTRY 2.1e6\n    FLEET["TSG_V1"] = TSG\n    M.sample_now(now=ist(9, 18), kite=k)                       # TSG ENTRY 4e5  → fleet 2.5e6\n    M.sample_now(now=ist(9, 20), kite=k)                       # TIMER both\n    FLEET["IC_V2"] = []\n    M.sample_now(now=ist(9, 21), kite=k)                       # IC CLOSED → fleet 4e5\n    rows = M._rows(30, now=ist(10, 0))\n    fc = M.fleet_concurrent(rows, "PAPER")\n    check("fleet at 09:17 = IC alone", fc[ist(9, 17)] == 2.1e6, fc)\n    check("fleet at 09:18 = IC carried forward + TSG entry", fc[ist(9, 18)] == 2.5e6, fc)\n    check("fleet at 09:21 = TSG only (IC CLOSED zeroes it)", fc[ist(9, 21)] == 4e5, fc)\n    s = M.summarise(rows)\n    ic = next(x for x in s["strategies"] if x["strategy_id"] == "IC_V2")\n    check("CLOSED rows excluded from strategy stats", ic["samples"] == 2 and ic["errors"] == 0, ic)\n    check("at-entry stats: 1 entry, median = peak = 2.1e6", ic["entries"] == 1 and ic["entry_median"] == 2.1e6 and ic["entry_peak"] == 2.1e6, ic)\n    check("fleet PAPER peak = 2.5e6 at 09:18 (an entry minute)", s["fleet"]["PAPER"]["peak"] == 2.5e6 and s["fleet"]["PAPER"]["peak_at"].endswith("09:18"), s["fleet"])\n    check("fleet resets at a new day", M.fleet_concurrent([{"ts": 1, "day": "a", "strategy_id": "X", "book": "PAPER", "n_legs": 1, "total": 5.0},\n                                                            {"ts": 2, "day": "b", "strategy_id": "Y", "book": "PAPER", "n_legs": 1, "total": 3.0}], "PAPER")[2] == 3.0)\n    check("summary route ok", M.get_summary(days=30)["ok"] is True)\n\n    print("── 8. migration / retention / overlap / job ──")\n    M, F, FLEET, db = setup()\n    with sqlite3.connect(db) as c:                             # first-version table, no trigger column\n        c.execute("CREATE TABLE margin_samples (ts INTEGER NOT NULL, day TEXT NOT NULL, hhmm TEXT NOT NULL,"\n                  " strategy_id TEXT NOT NULL, book TEXT NOT NULL, mode TEXT, n_legs INTEGER, base_lots REAL,"\n                  " total REAL, span REAL, exposure REAL, premium REAL, per_lot REAL, legs_json TEXT, error TEXT)")\n        c.execute("INSERT INTO margin_samples VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",\n                  (ist(10, 0, d=16), "2026-10-16", "10:00", "IC_V2", "PAPER", "PAPER", 4, 10, 1.1e6, None, None, None, 1.1e5, "[]", None))\n        c.execute("INSERT INTO margin_samples VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",\n                  (ist(10, 0, d=1, mo=1), "2026-01-01", "10:00", "IC_V2", "PAPER", "PAPER", 4, 10, 1e6, None, None, None, 1e5, "[]", None))\n    FLEET["IC_V2"] = IC\n    M.sample_now(now=ist(9, 17), kite=FakeKite())\n    with sqlite3.connect(db) as c:\n        cols = {r[1] for r in c.execute("PRAGMA table_info(margin_samples)")}\n        old = c.execute("SELECT COUNT(*) FROM margin_samples WHERE day=\'2026-01-01\'").fetchone()[0]\n    check("v1 table upgraded with a trigger column", "trigger" in cols)\n    s = M.summarise(M._rows(30, now=ist(10, 0)))\n    check("v1 rows still count as samples", next(x for x in s["strategies"] if x["strategy_id"] == "IC_V2")["samples"] == 2, s)\n    check(f"rows older than {M.KEEP_DAYS} days purged", old == 0)\n    M._lock.acquire()\n    try:\n        check("overlapping pass refused", M.sample_now(now=ist(9, 25), kite=FakeKite())["reason"] == "a sample is already running")\n    finally:\n        M._lock.release()\n    F._legs_for = lambda sid, w: (_ for _ in ()).throw(RuntimeError("boom"))\n    check("job never raises", M.margin_log_sample_job() is None)\n    r = M.sample_now(now=ist(9, 25), kite=FakeKite())\n    check("all strategies unreadable → no rows, nothing closed", r.get("sampled") and r["rows"] == 0, r)\n\n    if FAILS:\n        print(f"\\n{len(FAILS)} FAILURES: {FAILS}")\n        sys.exit(1)\n    print(f"\\nALL {OK[0]} MARGIN-LOG CHECKS PASSED")\n\n\nif __name__ == "__main__":\n    main()\n', 'frontend/src/components/MarginLog.jsx': '/* frontend/src/components/MarginLog.jsx — ── MARGIN_LOG_20261016 ── ── MARGIN_LOG_ENTRY_20261016 ──\n   "How much money does each strategy really need?" Reads the margin log the\n   backend samples from the OPEN paper and live legs via Zerodha\'s basket-margin\n   API — within a minute of every entry / leg change (from 09:17 IST) and every\n   5 min 09:20–15:25. Summary per strategy + book, fleet\n   concurrent peak per book, CSV export of every sample. Read-only; the only\n   write is "Sample now" (one manual pass). Strategy names go through\n   stratName(), so non-admin users never see a raw strategy id. */\nimport React, { useCallback, useEffect, useState } from "react";\nimport { getApiBase } from "../api/base";\nimport { colors, spacing, typography } from "../tokens";\nimport { exportToCSV } from "../utils/export";\nimport { stratName } from "../strategies/displayNames";\nimport { useEntitlements } from "../hooks/useEntitlements";\n\nconst TH = { padding: "8px 8px", textAlign: "right", ...typography.label, color: colors.text.muted,\n             borderBottom: `2px solid ${colors.border.light}`, fontWeight: 600, whiteSpace: "nowrap" };\nconst TD = { padding: "7px 8px", ...typography.bodyMedium, ...typography.mono, textAlign: "right", whiteSpace: "nowrap" };\nconst L = (v) => (v == null ? "—" : `₹${(Number(v) / 100000).toFixed(2)}L`);\nconst K = (v) => (v == null ? "—" : `₹${Math.round(Number(v)).toLocaleString("en-IN")}`);\nconst lots = (v) => (v == null ? "—" : (Math.round(Number(v) * 10) / 10).toString());\nconst when = (ts) => (ts ? new Date(ts * 1000).toLocaleString("en-IN", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit", hour12: false, timeZone: "Asia/Kolkata" }) : "—");\n\nexport default function MarginLog() {\n  const { loaded, isAdminUi } = useEntitlements();\n  const admin = !loaded || isAdminUi;\n  const [days, setDays] = useState(14);\n  const [book, setBook] = useState("ALL");\n  const [data, setData] = useState(null);\n  const [busy, setBusy] = useState(false);\n  const [msg, setMsg] = useState("");\n  const [open, setOpen] = useState(true);\n\n  const load = useCallback(async () => {\n    try {\n      const r = await fetch(`${getApiBase()}/api/margin-log/summary?days=${days}&book=${book}`);\n      setData(await r.json());\n    } catch (e) { setData({ ok: false, error: String(e.message || e), strategies: [], fleet: {} }); }\n  }, [days, book]);\n  useEffect(() => { load(); const t = setInterval(load, 60000); return () => clearInterval(t); }, [load]);\n\n  const sampleNow = useCallback(async () => {\n    setBusy(true); setMsg("");\n    try {\n      const r = await (await fetch(`${getApiBase()}/api/margin-log/sample-now`, { method: "POST" })).json();\n      setMsg(r.sampled ? `Sampled ${r.rows} position(s)${r.errors ? ` · ${r.errors} failed` : ""}${r.reason ? ` · ${r.reason}` : ""}` : `Not sampled: ${r.reason || "unknown"}`);\n      await load();\n    } catch (e) { setMsg(String(e.message || e)); } finally { setBusy(false); }\n  }, [load]);\n\n  const exportCsv = useCallback(async () => {\n    try {\n      const r = await (await fetch(`${getApiBase()}/api/margin-log/samples?days=${days}&book=${book}`)).json();\n      const rows = (r.rows || []).map((x) => ({\n        day: x.day, time: x.hhmm, strategy: stratName(x.strategy_id, admin, x.strategy_id), book: x.book, mode: x.mode,\n        trigger: x.trigger || "TIMER",\n        legs: x.n_legs, lots: x.base_lots, margin_total: x.total, span: x.span, exposure: x.exposure,\n        option_premium: x.premium, margin_per_lot: x.per_lot, error: x.error || "", legs_detail: x.legs_json,\n      }));\n      if (!rows.length) { setMsg("Nothing to export yet."); return; }\n      exportToCSV(rows, `margin_log_${days}d_${book.toLowerCase()}.csv`);\n    } catch (e) { setMsg(String(e.message || e)); }\n  }, [days, book, admin]);\n\n  const S = (data && data.strategies) || [];\n  const F = (data && data.fleet) || {};\n  const sel = { padding: "5px 8px", borderRadius: 6, border: `1px solid ${colors.border.light}`, background: colors.bg.tertiary,\n                color: colors.text.primary, fontSize: 12 };\n  const btn = { ...sel, cursor: "pointer", fontWeight: 600 };\n  return (\n    <div style={{ background: colors.bg.secondary, border: `1px solid ${colors.border.light}`, borderRadius: 8,\n                  boxShadow: "0 1px 3px var(--c-shadow)", marginTop: spacing.xl, padding: spacing.lg }}>\n      <div style={{ display: "flex", alignItems: "center", gap: spacing.md, flexWrap: "wrap" }}>\n        <button onClick={() => setOpen((v) => !v)} style={{ ...btn, background: "transparent", border: "none", padding: 0,\n                fontSize: 15, color: colors.text.primary }} title="Show / hide">\n          {open ? "▾" : "▸"} Margin log\n        </button>\n        <span style={{ fontSize: 12, color: colors.text.muted }}>\n          Zerodha basket margin of each strategy\'s open legs · at every entry / leg change (from 09:17) and every 5 min · paper and live kept apart\n        </span>\n        <div style={{ flex: 1 }} />\n        <select value={days} onChange={(e) => setDays(Number(e.target.value))} style={sel}>\n          {[3, 7, 14, 30, 90].map((d) => <option key={d} value={d}>Last {d} days</option>)}\n        </select>\n        <select value={book} onChange={(e) => setBook(e.target.value)} style={sel}>\n          <option value="ALL">Paper + Live</option><option value="PAPER">Paper</option><option value="LIVE">Live</option>\n        </select>\n        <button onClick={sampleNow} disabled={busy} style={btn}>{busy ? "Sampling…" : "Sample now"}</button>\n        <button onClick={exportCsv} style={btn}>Export CSV</button>\n      </div>\n      {msg && <div style={{ fontSize: 12, color: colors.text.secondary, marginTop: 6 }}>{msg}</div>}\n      {open && (\n        <div style={{ marginTop: spacing.md }}>\n          {data && data.ok === false && <div style={{ color: colors.loss, fontSize: 12 }}>Margin log unavailable: {data.error}</div>}\n          {!S.length ? (\n            <div style={{ fontSize: 12, color: colors.text.muted, padding: "8px 0" }}>\n              No samples yet. They start on the next market-hours tick while any strategy holds a position — or press “Sample now”.\n            </div>\n          ) : (\n            <div style={{ overflowX: "auto" }}>\n              <table style={{ width: "100%", borderCollapse: "collapse" }}>\n                <thead><tr>\n                  <th style={{ ...TH, textAlign: "left" }}>Strategy</th><th style={{ ...TH, textAlign: "left" }}>Book</th>\n                  <th style={TH}>Days</th><th style={TH}>Samples</th><th style={TH}>Lots</th>\n                  <th style={TH}>Median</th><th style={TH}>P90</th><th style={TH}>Peak</th>\n                  <th style={TH} title="Margin sampled within a minute of the position being opened">At entry · median</th>\n                  <th style={TH}>At entry · peak</th>\n                  <th style={TH}>Per lot · median</th><th style={TH}>Per lot · peak</th><th style={TH}>Last</th>\n                </tr></thead>\n                <tbody>\n                  {S.map((r) => (\n                    <tr key={r.strategy_id + r.book} style={{ borderBottom: `1px solid ${colors.border.light}` }}>\n                      <td style={{ ...TD, ...typography.bodyMedium, textAlign: "left", fontWeight: 600 }}>{stratName(r.strategy_id, admin, r.strategy_id)}</td>\n                      <td style={{ ...TD, textAlign: "left", color: r.book === "LIVE" ? colors.warning : colors.text.secondary }}>{r.book}</td>\n                      <td style={TD}>{r.days}</td>\n                      <td style={TD} title={r.errors ? `${r.errors} failed sample(s) — last: ${r.last_error}` : ""}>\n                        {r.samples}{r.errors ? <span style={{ color: colors.loss }}> (+{r.errors}✕)</span> : null}</td>\n                      <td style={TD} title={r.lots_max !== r.lots_typical ? `up to ${lots(r.lots_max)}` : ""}>{lots(r.lots_typical)}</td>\n                      <td style={TD}>{L(r.median)}</td><td style={TD}>{L(r.p90)}</td>\n                      <td style={{ ...TD, fontWeight: 700, lineHeight: 1.25 }}>{L(r.peak)}\n                        {r.peak_at && <div style={{ fontSize: 10, fontWeight: 400, color: colors.text.muted }}>{r.peak_at.slice(5)}{r.peak_lots ? ` · ${lots(r.peak_lots)}L` : ""}</div>}</td>\n                      <td style={TD} title={r.entries ? `${r.entries} entr${r.entries === 1 ? "y" : "ies"} recorded` : "no entry recorded yet"}>{L(r.entry_median)}</td>\n                      <td style={TD}>{L(r.entry_peak)}</td>\n                      <td style={TD}>{K(r.per_lot_median)}</td><td style={TD}>{K(r.per_lot_peak)}</td>\n                      <td style={{ ...TD, color: colors.text.muted }}>{when(r.last_ts)}</td>\n                    </tr>\n                  ))}\n                  {["PAPER", "LIVE"].filter((b) => F[b]).map((b) => (\n                    <tr key={"fleet" + b} style={{ background: colors.bg.tertiary }}>\n                      <td style={{ ...TD, ...typography.bodyMedium, textAlign: "left", fontWeight: 700 }} colSpan={2}>Fleet at once · {b}</td>\n                      <td style={TD} /><td style={TD}>{F[b].samples}</td><td style={TD} />\n                      <td style={TD}>{L(F[b].median)}</td><td style={TD}>{L(F[b].p90)}</td>\n                      <td style={{ ...TD, fontWeight: 700, lineHeight: 1.25 }}>{L(F[b].peak)}\n                        <div style={{ fontSize: 10, fontWeight: 400, color: colors.text.muted }}>{(F[b].peak_at || "").slice(5)}</div></td>\n                      <td style={TD} colSpan={5} />\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n          )}\n          <div style={{ fontSize: 11, color: colors.text.muted, marginTop: 8, lineHeight: 1.5 }}>\n            Lots = the largest sell leg (or the largest leg for buy-only strategies); per lot = margin ÷ those lots.\n            “At entry” = sampled within a minute of the position opening (09:16 entries are measured at 09:17, clear of the opening order burst).\n            “Fleet at once” = every strategy of a book at its latest sampled margin, added up at each sample time — what the account has to hold together.\n            Margin between samples is not seen — keep a buffer above the peak.\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'}

A_OLD = '        # ── MARGIN_LOG_20261016 ── basket margin of every strategy\'s open\n        # legs (paper + live, separately) every 5 min; the 09:20–15:25 +\n        # holiday gate lives in the job. Read-only; never raises; own id.\n        scheduler.add_job(\n            margin_log_sample_job, trigger="cron", day_of_week="mon-fri",\n            hour="9-15", minute="*/5", id="margin_log_sampler",\n            replace_existing=True, timezone="Asia/Kolkata")\n'
A_NEW = '        # ── MARGIN_LOG_20261016 ── basket margin of every strategy\'s open\n        # legs (paper + live, separately). Read-only; never raises; own id.\n        # ── MARGIN_LOG_ENTRY_20261016 ── every minute now: a margin call on\n        # each ENTRY / leg CHANGE from 09:17 (clear of the 09:16 burst), a\n        # TIMER pass every 5th minute 09:20–15:25; the gates live in the job.\n        scheduler.add_job(\n            margin_log_sample_job, trigger="cron", day_of_week="mon-fri",\n            hour="9-15", minute="*", id="margin_log_sampler",\n            replace_existing=True, timezone="Asia/Kolkata")\n'


def die(m):
    print(f"\n✗ {m}"); sys.exit(1)


def main():
    ap = argparse.ArgumentParser()
