    ap.add_argument("--allow-dirty", action="store_true")
    ap.add_argument("--skip-tests", action="store_true")
    a = ap.parse_args()
    repo = Path(a.repo).expanduser().resolve()
    api = (repo / A).read_text(encoding="utf-8") if (repo / A).exists() else die(f"missing {A}")
    if FENCE in api:
        die(f"{A} already carries {FENCE} — already applied, nothing to do")
    if PARENT not in api:
        die(f"{PARENT} not applied — run apply_margin_log.py first, then this script")
